create schema b; create macro b.helper() as 10; create macro helper() as 1; create macro b.outer() as helper(); create sequence b.s; create sequence s; create type b.mood as enum ('a'); create type mood as enum ('a', 'b'); create macro valid(x) as x <> ''; create macro b.valid(x) as length(x) > 0; create table b.t (id bigint primary key default nextval('s'), m mood, c varchar check (valid(c) and c::mood <> 'b'), d boolean default valid('x'), n integer check (n < b.outer()));
